//! What the C run-time's startup gives an MSVC program: the entry point and the TLS
//! directory.

use core::ffi::c_void;
use core::ptr;

use crate::sys;

extern "C" {
    /// Generated by rustc for a program's `fn main` (it calls std's `lang_start`).
    fn main(argc: i32, argv: *const *const u8) -> i32;
}

/// The entry point the linker gives a console or GUI program. std takes the command line
/// from `GetCommandLineW`, so `main` gets no arguments; its result is the exit code.
#[no_mangle]
pub unsafe extern "C" fn mainCRTStartup() -> ! {
    // SAFETY: main is rustc's entry; ExitProcess does not return.
    unsafe { sys::ExitProcess(main(0, ptr::null()) as u32) }
}

/// A TLS callback: `(module, reason, reserved)`.
type TlsCallback = unsafe extern "system" fn(*mut c_void, u32, *mut c_void);

/// The TLS directory of the image (IMAGE_TLS_DIRECTORY), which the linker points the
/// image's TLS entry at when it finds `_tls_used`. NT 4.0's loader then calls the callbacks
/// listed between `.CRT$XLA` and `.CRT$XLZ` when a thread starts and ends; std puts its
/// own in `.CRT$XLB` to run the destructors of its thread-locals. The TLS data template is
/// empty (one byte): this target has no `#[thread_local]` variables.
#[repr(C)]
pub struct TlsDirectory {
    start_of_raw_data: *const u8,
    end_of_raw_data: *const u8,
    address_of_index: *const u32,
    address_of_callbacks: *const Option<TlsCallback>,
    size_of_zero_fill: u32,
    characteristics: u32,
}

// SAFETY: read-only, read by the loader.
unsafe impl Sync for TlsDirectory {}

#[link_section = ".tls"]
#[used]
static TLS_START: u8 = 0;

#[link_section = ".tls$ZZZ"]
#[used]
static TLS_END: u8 = 0;

#[used]
static mut TLS_INDEX: u32 = 0;

#[link_section = ".CRT$XLA"]
#[used]
static XL_A: Option<TlsCallback> = None;

#[link_section = ".CRT$XLZ"]
#[used]
static XL_Z: Option<TlsCallback> = None;

#[cfg_attr(not(target_arch = "x86"), export_name = "_tls_used")]
#[cfg_attr(target_arch = "x86", export_name = "__tls_used")]
#[used]
pub static TLS_USED: TlsDirectory = TlsDirectory {
    start_of_raw_data: &raw const TLS_START,
    end_of_raw_data: &raw const TLS_END,
    address_of_index: &raw const TLS_INDEX,
    // The callbacks start after XL_A's empty slot; XL_Z's ends the list.
    address_of_callbacks: (&raw const XL_A).wrapping_add(1),
    size_of_zero_fill: 0,
    characteristics: 0,
};
